def _feasible(sizes, caps, j=0):
    # Brute force: assign each group (in order) a subset of distinct numbers
    # with remaining capacity; every group j must have exactly sizes[j] members.
    if j == len(sizes):
        return True
    avail = [i for i in range(len(caps)) if caps[i] > 0]
    for combo in combinations(avail, sizes[j]):
        for i in combo:
            caps[i] -= 1
        ok = _feasible(sizes, caps, j + 1)
        for i in combo:
            caps[i] += 1
        if ok:
            return True
    return False


def ref(inp):
    u = json.loads(inp.strip().split("\n")[0])
    n = len(u)
    best = 0
    # Every strictly increasing sequence of group sizes corresponds to a
    # subset of {1..n}; try all subsets and keep the largest feasible one.
    for mask in range(1 << n):
        sizes = [i + 1 for i in range(n) if (mask >> i) & 1]
        if not sizes:
            continue
        if len(sizes) > best and _feasible(sizes, list(u)):
            best = len(sizes)
    return json.dumps(best)
