import json
from itertools import combinations
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(1, 5))
    u = draw(st.lists(st.integers(1, 3), min_size=n, max_size=n))
    return json.dumps(u)


def validate(inp):
    try:
        lines = inp.strip().split("\n")
        if len(lines) != 1:
            return False
        u = json.loads(lines[0])
    except Exception:
        return False
    if not isinstance(u, list):
        return False
    n = len(u)
    if not (1 <= n <= 10**5):
        return False
    for x in u:
        if type(x) is not int or not (1 <= x <= 10**9):
            return False
    return True


def _feasible(sizes, caps):
    # Can we choose, for each group g in order, a set of sizes[g] distinct
    # numbers such that every number i is chosen at most caps[i] times overall?
    n = len(caps)

    def place(g, cur):
        if g == len(sizes):
            return True
        avail = [i for i in range(n) if cur[i] > 0]
        for combo in combinations(avail, sizes[g]):
            nxt = list(cur)
            for i in combo:
                nxt[i] -= 1
            if place(g + 1, nxt):
                return True
        return False

    return place(0, list(caps))


def ref(inp):
    u = json.loads(inp.strip())
    n = len(u)
    best = 0
    # Try every number k of groups and every strictly increasing sequence of
    # nonempty group sizes (each size in 1..n) of length k; a sequence is
    # achievable iff the exhaustive placement succeeds.
    for k in range(1, n + 1):
        for sizes in combinations(range(1, n + 1), k):
            if _feasible(list(sizes), u):
                best = max(best, k)
    return json.dumps(best)
